-- Table: transaction_delivery_detail
-- Source: accounting_admin_db.sql (3. Sales flow)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS transaction_delivery_detail (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    delivery_id          BIGINT NOT NULL REFERENCES transaction_delivery(id) ON DELETE CASCADE,
    line_number          INTEGER NOT NULL CHECK (line_number > 0),
    sales_order_detail_id BIGINT REFERENCES transaction_sales_order_detail(id),
    product_id           BIGINT NOT NULL REFERENCES masterdata_product(id),
    description          TEXT,
    quantity             NUMERIC(18,4) NOT NULL CHECK (quantity > 0),
    uom_id               BIGINT NOT NULL REFERENCES masterdata_uom(id),
    weight_kg            NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK (weight_kg >= 0),
    UNIQUE (delivery_id, line_number)
);
